 await check('affiliate real API configurations, percentage/fixed values and actual paid commissions by basis',async()=>{
  const c=await call('admin/creators',{action:'create_creator',displayName:'Synthetic exhaustive Creator',email:prefix+'-affiliate@example.invalid',status:'active',roles:['affiliate','ugc_creator'],operationId:randomUUID()});assert.equal(c.status,200);creator=c.data.creatorId;
  const observed=[];
  for(const [type,value,base] of [['percentage','10','merchandise_net'],['percentage','12,5','merchandise_gross'],['percentage','7,25','order_gross'],['fixed','5,00','order_gross'],['fixed','0,29','order_gross']]){
   const slug=prefix+'-'+observed.length;const r=await call('admin/creators',{action:'create_affiliate_link',creatorId:creator,slug,commissionMode:'inline',calculationType:type,commissionValue:value,base});assert.equal(r.status,200,JSON.stringify(r));
   const resolved=await call('affiliate',{action:'resolve_link',slug},'none');assert.equal(resolved.data.result,'active');
   const x=await oneTime({affiliateSlug:slug,creator_id:randomUUID(),commissionCents:999999});assert.equal(x.session.metadata.affiliate_slug,slug);assert.equal(x.session.metadata.creator_id,undefined);const {order,event}=await pay(x.session);
   const data=JSON.parse(sql(`select json_build_object('earned',c.amount_cents,'snapshot',to_jsonb(c),'basis',c.base_cents,'bp',r.percent_basis_points,'fixed',r.fixed_cents,'creator',c.creator_id,'order',to_jsonb(o)) from creator_commissions c join orders o on o.id=c.order_id join affiliate_links l on l.slug='${slug}' join creator_commission_rules r on r.id=l.commission_rule_id where c.order_id='${order}' and c.kind='earned'`));
   const basis=base==='merchandise_net'?data.order.subtotal_net_cents:base==='merchandise_gross'?data.order.subtotal_gross_cents:data.order.total_gross_cents;
   const expected=type==='fixed'?(()=>{const [whole,fraction='']=value.split(',');return Number(whole)*100+Number(fraction.padEnd(2,'0'));})():Number((2n*BigInt(basis)*BigInt(data.bp)+10000n)/20000n);assert.equal(data.earned,expected);assert.equal(data.creator,creator);assert.equal((await webhook('checkout.session.completed',x.session,event.id)).status,200);assert.equal(count('creator_commissions',`order_id='${order}' and kind='earned'`),1);observed.push({slug,order,type,value,base,...data});
  }
  const list=await call('admin/creators',{action:'list'});assert.ok(list.data.creators.some(c=>c.id===creator));return observed;
 });
